local module = {}
module.__index = module

function module.new(configs: IConfiguration)
	local self = setmetatable({}, module)
	self._config = configs.NezaBootstrapConfig
	assert(self._config, "NezaBootstrapConfig is required")
	return self
end

function module:Start()
	require(game.ReplicatedStorage.Packages.Neza):Boot(self._config)
end

function module:Dispose() end

return module
